import{_ as r}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as t,o as e,c as i,a3 as l}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"환영","description":"MiniTavern Ultra 가이드 — 모바일 AI 롤플레이, 캐릭터 카드, BYOK, Ollama/LM Studio. SillyTavern 스타일 채팅을 iOS/Android에서.","frontmatter":{"title":"환영","description":"MiniTavern Ultra 가이드 — 모바일 AI 롤플레이, 캐릭터 카드, BYOK, Ollama/LM Studio. SillyTavern 스타일 채팅을 iOS/Android에서.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"환영 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra 가이드 — 모바일 AI 롤플레이, 캐릭터 카드, BYOK, Ollama/LM Studio. SillyTavern 스타일 채팅을 iOS/Android에서."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko"}]]},"headers":[],"relativePath":"ko/index.md","filePath":"ko/index.md","lastUpdated":1787224147000}'),o={name:"ko/index.md"};function n(d,a,s,u,g,h){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="환영" tabindex="-1">환영 <a class="header-anchor" href="#환영" aria-label="Permalink to &quot;환영&quot;">​</a></h1><div class="overview-hero"><p><img src="'+r+'" alt="MiniTavern Ultra"></p></div><h2 id="앱-소개" tabindex="-1">앱 소개 <a class="header-anchor" href="#앱-소개" aria-label="Permalink to &quot;앱 소개&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong>는 <strong>AI 롤플레이 채팅</strong> 앱입니다.</p><p><strong>AI 파트너를 만들고, 이야기를 연기하세요</strong> — 카드 한 장에서, 원하는 방식으로 시작하세요.</p><p>원하는 캐릭터 카드를 가져오거나 만들고, 클라우드·로컬 모델에 <strong>BYOK</strong>로 연결하세요. 키와 데이터는 기기 우선으로 남습니다.</p><h2 id="할-수-있는-일" tabindex="-1">할 수 있는 일 <a class="header-anchor" href="#할-수-있는-일" aria-label="Permalink to &quot;할 수 있는 일&quot;">​</a></h2><ol><li><p><strong>나만의 AI 파트너 만들기</strong><br> 성격·말투·관계를 직접 정해, 「나만 아는」 상대처럼 쓰세요. 일상 대화·동반에 적합합니다.</p></li><li><p><strong>아이돌·원작 캐릭터를 「곁에」</strong><br> 커뮤니티 캐릭터 카드（SillyTavern 계열 형식）를 가져와, 익숙한 말투로 일상이나 이야기를 이어 가세요.</p></li><li><p><strong>장편 스토리·연출</strong><br> 월드북으로 설정을 고정하고, 정규식으로 표시를 다듬으세요. 세션마다 모델·외관을 따로 묶을 수 있습니다.</p></li><li><p><strong>내 모델, 내 리듬</strong><br><strong>BYOK</strong>: API Key로 클라우드에 직결하거나, PC의 Ollama / LM Studio에 연결. 유료 한도가 없으면 <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a>; PC 배포는 <a href="/ultra_guides/ko/local/">로컬 모델</a>.</p></li></ol><h2 id="왜-minitavern인가" tabindex="-1">왜 MiniTavern인가 <a class="header-anchor" href="#왜-minitavern인가" aria-label="Permalink to &quot;왜 MiniTavern인가&quot;">​</a></h2><ul><li><strong>한 장, 두 가지 열기</strong>: 일상 동반 또는 연기 입문, 같은 입구</li><li><strong>캐릭터 카드 우선</strong>: PNG / JSON 가져오기·미리보기, 창작과 채팅이 한 줄로</li><li><strong>사설 API</strong>: 키는 내가 통제, 단일 채널에 잠기지 않음</li><li><strong>고급 플레이</strong>: 월드북, 정규식, 페르소나, 인터랙티브 카드면</li><li><strong>데이터 이동</strong>: 백업·단톡 아카이브로 기기 교체도 안심</li></ul><h2 id="빠른-시작" tabindex="-1">빠른 시작 <a class="header-anchor" href="#빠른-시작" aria-label="Permalink to &quot;빠른 시작&quot;">​</a></h2><ol><li><strong>모델 설정</strong>: 설정 → <a href="/ultra_guides/ko/manual/model-link">모델 연결</a> → 새로 만들기·테스트 → 기본값.</li><li><strong>캐릭터</strong>: 캐릭터 카드 → <a href="/ultra_guides/ko/manual/chara-card">가져오기 / 만들기</a>.</li><li><strong>채팅</strong>: 캐릭터에서 열기 — 동반이든 연기든 선택.</li></ol><p>자세한 단계: <a href="/ultra_guides/ko/manual/getting-started">처음 사용</a>. PC 배포: <a href="/ultra_guides/ko/local/">로컬 개요</a> · <a href="/ultra_guides/ko/quickstart">30분 퀵스타트</a> · <a href="/ultra_guides/ko/local/image-gen/">이미지</a>. 무료 한도: <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a>.</p><h2 id="매뉴얼-입구" tabindex="-1">매뉴얼 입구 <a class="header-anchor" href="#매뉴얼-입구" aria-label="Permalink to &quot;매뉴얼 입구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구역</th><th>설명</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ko/manual/">매뉴얼 홈</a></td><td>권장 읽기 순서·총괄</td></tr><tr><td><a href="/ultra_guides/ko/manual/model-link">모델</a></td><td>연결·파라미터·테스트·오류</td></tr><tr><td><a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a></td><td>각사 무료 한도와 Key 입력</td></tr><tr><td><a href="/ultra_guides/ko/local/">로컬 모델</a></td><td>언어 / 이미지 PC 배포</td></tr><tr><td><a href="/ultra_guides/ko/manual/chara-card">캐릭터</a></td><td>가져오기·편집·개채</td></tr><tr><td><a href="/ultra_guides/ko/manual/chat">채팅</a></td><td>대화와 세션 설정</td></tr><tr><td><a href="/ultra_guides/ko/manual/lorebook">고급</a></td><td>월드북·정규식·페르소나·백업</td></tr></tbody></table><p>앱 내: 설정 → <strong>도움말과 피드백</strong> → <strong>사용자 매뉴얼</strong>.</p><h2 id="faq-요약" tabindex="-1">FAQ（요약） <a class="header-anchor" href="#faq-요약" aria-label="Permalink to &quot;FAQ（요약）&quot;">​</a></h2><p><strong>Q: MiniTavern Ultra란?</strong><br> A: AI 롤플레이 채팅 앱입니다. 파트너를 만들거나 카드를 가져와 연기하고, 본인 API Key 또는 로컬 모델로 대화합니다.</p><p><strong>Q: 데이터가 서버로 올라가나요?</strong><br> A: 채팅·캐릭터·키 등은 기본적으로 기기에 둡니다. 모델 호출은 설정한 제3자 또는 로컬 주소로 갑니다. <a href="/ultra_guides/ko/privacy">개인정보</a>.</p><p><strong>Q: API 없이 쓸 수 있나요?</strong><br> A: 클라우드 Key를 준비하거나 <a href="/ultra_guides/ko/local/">로컬 모델</a>로 PC에 서비스를 올린 뒤 폰을 연결하세요. 무료 한도: <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a>; 로컬 이미지: <a href="/ultra_guides/ko/local/image-gen/">이미지 모델 배포</a>.</p><h2 id="다운로드·정책" tabindex="-1">다운로드·정책 <a class="header-anchor" href="#다운로드·정책" aria-label="Permalink to &quot;다운로드·정책&quot;">​</a></h2><ul><li>상단 <strong>MiniTavern 다운로드</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">제품 공식 사이트</a></li><li><a href="/ultra_guides/ko/privacy">개인정보</a> · <a href="/ultra_guides/ko/terms">이용약관</a></li></ul>',22)])])}const m=t(o,[["render",n]]);export{_ as __pageData,m as default};
